DROP TABLE IF EXISTS `entity_table`;
CREATE TABLE `entity_table`  (
  `data_id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `object` varchar(1024) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '第n位对应property_id=n',
  `operate` varchar(1024) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '第n位对应property_id=n',
  `result` varchar(1024) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '第n位对应property_id=n',
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `data_producers` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `data_organizations` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  PRIMARY KEY (`data_id`) USING BTREE,
  INDEX `idx_object`(`object`(255) ASC) USING BTREE,
  INDEX `idx_operate`(`operate`(255) ASC) USING BTREE,
  INDEX `idx_result`(`result`(255) ASC) USING BTREE,
  INDEX `idx_entity_title_data_id`(`title` ASC, `data_id` ASC) USING BTREE,
  INDEX `idx_entity_table_title`(`title` ASC) USING BTREE,
  INDEX `idx_entity_table_title_data_id`(`title` ASC, `data_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 50926377 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

